// adopted from @Metamere
// https://openprocessing.org/sketch/2272174/

var NUM = 5;
var S, S2;

function setup() {
  let D = max(windowWidth, windowHeight);
  S = D / NUM;
	S2 = S/2;
  createCanvas(D, D);
	frameRate(1);
}

function mousePressed() {
  if (mouseButton === LEFT) loop();
}

function draw() {
  background("rgb(130,218,177)");

  for (let y = 0; y < NUM; y++) {
    for (let x = 0; x < NUM; x++) {
      drawCirc(x * S + S2, y * S + S2, S * 0.9);
    }
  }

  // // noLoop() removed for animation
}

function drawCirc(xc, yc, s) {
	var S = s;
	const S2 = s/2;
  push();
  noStroke();

	// colors
	const clr1 = color("darkorange")
	const clr2 = color("darkred")

	// mask | { invert: true }
	beginClip(); 
  circle(xc, yc, s);
  endClip();

	// fragments in circle
  let y = 0;
  while (y < S) {
		// height
    const h = ~~random(S * 0.075, S * 0.25);
		// const h = randomGaussian(S * 0.1, S * 0.01);

		// padding
		const p = ~~random(S * 0.05, S * 0.25)
		// const p = randomGaussian(S * 0.05, S * 0.01);

		// function fill(lerpColor(clr1, clr2, random(0.25)))

		// stripe
		if (y + h + p < S * 0.95) {
			rect(xc -S2, yc+y -S2, s, h)
		} else {
			rect(xc -S2, yc+y -S2, s, s-y)
			y = S;
		}

    y += h + p; // increment by height + padding
  }

  pop();
}
